import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Ajustar o contraste leva só alguns minutos. Você envia a foto, arrasta um controle, confere os realces e as sombras e baixa a versão com mais impacto.</p>\n<p>Este passo a passo cobre o processo inteiro. Você vai ver o controle, as predefinições rápidas, os modos de comparação e as configurações de exportação que mantêm o resultado natural.</p>\n<p>No final, você vai conseguir corrigir uma paisagem chapada, suavizar um retrato duro ou afiar uma captura de tela sem graça em qualquer dispositivo. Guarde a foto original até conferir o resultado.</p>\n<h2 id=\"before-you-start\">Antes de começar: diagnostique a foto</h2>\n<p>Olhe a foto antes de abrir a ferramenta. Ela está chapada e cinza, dura com sombras profundas, ou com a amplitude certa? A resposta diz para que direção mover o controle.</p>\n<p>Uma foto chapada precisa de um reforço positivo de 10 a 20 por cento. Uma foto dura precisa de um movimento negativo de 10 a 20 por cento para suavizar os extremos.</p>\n<p>Confira se a foto também está escura ou clara demais. Uma foto escura e chapada precisa de brilho primeiro, porque só o contraste não corrige o nível.</p>\n<p>Abra o <a href=\"/pt/ajustar-contraste-da-imagem/\">Ajustar contraste da foto</a> no seu navegador. Tudo roda localmente, então sua foto nunca é enviada para um servidor.</p>\n<h2 id=\"step-by-step\">Ajuste o contraste em cinco passos</h2>\n<p>O processo é o mesmo para uma foto, uma captura de tela ou um documento digitalizado. Envie, ajuste, compare, exporte e confira o download.</p>\n<p>Leve o controle com calma. Movimentos pequenos fazem uma grande diferença, e a prévia mostra exatamente quando a foto fica certa.</p>\n<ol>\n<li>Envie sua imagem arrastando-a para a área de envio, escolhendo-a no seu dispositivo ou colando uma captura de tela com Ctrl+V.</li>\n<li>Arraste o controle Nível de contraste para a direita para aumentar o contraste ou para a esquerda para diminuir, observando a prévia ao vivo.</li>\n<li>Teste um ajuste pronto para ver o resultado em um clique e depois afine com o controle se estiver perto, mas não exato.</li>\n<li>Use os modos de comparação para conferir os realces e as sombras contra a original antes de baixar.</li>\n<li>Escolha o formato e a qualidade de exportação e clique em Baixar para salvar a imagem ajustada.</li>\n</ol>\n<p>Abra o arquivo baixado uma vez antes de usá-lo. Confirme que a foto parece marcante sem perder detalhe nas áreas claras ou escuras.</p>\n<h2 id=\"using-the-slider\">Como usar o controle de contraste</h2>\n<p>O controle vai de valores negativos a positivos, com zero significando nenhuma mudança. Mover para a direita aumenta o contraste, e mover para a esquerda diminui.</p>\n<p>Arraste devagar e observe a prévia. A atualização ao vivo mostra exatamente como a imagem reage, então você pode parar no ponto em que a foto fica certa.</p>\n<p>Movimentos pequenos são melhores que os grandes. Uma mudança de 10 a 20 por cento costuma bastar, e movimentos maiores cortam os realces e esmagam as sombras rapidinho.</p>\n<p>A ferramenta mostra sua foto em mais 20 por cento logo depois do envio. Esse ponto de partida já dá uma ideia imediata de como fica um reforço moderado de contraste.</p>\n<h2 id=\"using-quick-presets\">Como usar as predefinições rápidas</h2>\n<p>A ferramenta inclui predefinições rápidas que aplicam valores comuns de contraste num só clique. São um jeito rápido de testar níveis diferentes sem arrastar o controle.</p>\n<p>Clique numa predefinição e olhe a prévia. Se o resultado estiver perto, mas não exato, ajuste com o controle a partir daquele ponto.</p>\n<p>Use as predefinições para comparar opções rapidinho. Uma predefinição em mais 10 por cento ao lado de uma em mais 30 por cento mostra quanto contraste a foto aguenta.</p>\n<p>Para um lote de fotos parecidas, a mesma predefinição mantém os resultados consistentes. Um conjunto de paisagens com neblina, todas com o mesmo reforço, parece uma série.</p>\n<h2 id=\"using-compare-modes\">Como usar os modos de comparação</h2>\n<p>Os modos de comparação mostram a original e a versão editada juntas. O modo Depois mostra a imagem com mais contraste, e o modo Antes mostra a original.</p>\n<p>A comparação dividida é a mais útil para o trabalho de contraste. Ela mostra as duas versões lado a lado, para você ver exatamente quais sombras aprofundaram e quais realces clarearam.</p>\n<p>A comparação em tela cheia mostra a foto maior. É o melhor jeito de avaliar uma edição de contraste, porque a imagem em tamanho real mostra cortes que uma prévia pequena esconde.</p>\n<p>Confira a comparação antes de cada download. Uma olhada rápida pega realces cortados e sombras esmagadas que uma prévia pequena poderia esconder.</p>\n<h2 id=\"boosting-a-flat-photo\">Como dar impacto a uma foto chapada</h2>\n<p>Envie a foto chapada e arraste o controle para mais 15 por cento. Confira a prévia: as sombras devem aprofundar, os realces devem clarear e a imagem deve parecer sólida.</p>\n<p>Se a foto continuar chapada, aumente o controle em passos pequenos de 5 por cento. Cada passo adiciona um pouco mais de impacto, e a prévia mostra quando parar.</p>\n<p>Observe os realces enquanto ajusta. Nuvens, camisas brancas e pele clara vão cortar primeiro, virando manchas brancas sem detalhe.</p>\n<p>Se a foto parecer dura depois do reforço, reduza o controle em 5 por cento. Uma pequena redução costuma restaurar o detalhe sem deixar a foto chapada de novo.</p>\n<h2 id=\"softening-a-harsh-photo\">Como suavizar uma foto dura</h2>\n<p>Arraste o controle para a esquerda para uma foto tirada sob o sol forte do meio-dia. Valores negativos, como menos 10 ou menos 20 por cento, suavizam as sombras fortes no rosto.</p>\n<p>Confira o rosto enquanto suaviza. As sombras devem se dissolver num visual mais gentil, enquanto a forma geral do rosto continua clara e definida.</p>\n<p>O contraste negativo também combina com paisagens suaves e de sonho. Uma cena de manhã com névoa e baixo contraste parece calma e silenciosa, o que combina com o clima da foto.</p>\n<p>Não exagere. Uma foto com pouco contraste demais parece cinza e sem vida, como se tivesse sido tirada através de nevoeiro, mesmo num dia limpo.</p>\n<h2 id=\"fixing-a-screenshot\">Como corrigir uma captura de tela sem graça</h2>\n<p>Cole uma captura de tela direto com Ctrl+V para pular a etapa de salvar. A imagem aparece no editor na hora, pronta para ajustar.</p>\n<p>Aumente o contraste até o texto ficar escuro e o fundo branco. Um documento com texto preto forte sobre um fundo branco limpo é fácil de ler e de imprimir.</p>\n<p>Cuidado com o ruído no fundo. Uma digitalização com muito contraste pode mostrar manchas e artefatos, principalmente num JPEG que já estava comprimido.</p>\n<p>Exporte capturas de tela em PNG. O formato sem perda mantém o texto pequeno nítido, o que importa quando a captura mostra uma configuração ou uma mensagem de erro.</p>\n<h2 id=\"checking-shadows-highlights\">Como conferir sombras e realces</h2>\n<p>Depois de cada mudança de contraste, confira as partes mais escuras e mais claras da imagem separadamente. As sombras esmagam primeiro com um reforço, e os realces cortam primeiro com o mesmo movimento.</p>\n<p>Dê zoom numa área de sombra e confirme que ela ainda mostra detalhe. Um casaco, uma árvore ou um canto escuro devem ter textura visível, não uma mancha preta sólida.</p>\n<p>Dê zoom numa área de realce e confirme que ela ainda mostra detalhe. Uma nuvem, uma camisa branca ou uma testa clara devem ter forma visível, não um branco vazio.</p>\n<p>Se algum extremo perdeu detalhe, reduza o controle em 5 por cento e confira de novo. Pequenas reduções geralmente restauram o detalhe sem tirar o impacto.</p>\n<h2 id=\"previewing\">Prévia antes de baixar</h2>\n<p>Confira sempre a prévia antes de baixar. Veja se a foto parece marcante, se nenhuma área clara virou branco e se nenhuma área escura virou preto.</p>\n<p>Use a comparação dividida para conferir a mudança. Ela mostra a original e a versão editada lado a lado, para você ver exatamente o que o contraste fez.</p>\n<p>Dê zoom nas áreas claras e escuras em tamanho real. Um céu ou uma sombra que parece bom numa prévia pequena pode estar cortado ou esmagado quando visto grande.</p>\n<p>Se o resultado parecer duro, reduza o controle em 5 por cento e confira de novo. Pequenas reduções costumam restaurar o detalhe sem deixar a foto chapada de novo.</p>\n<h2 id=\"choosing-export-format\">Como escolher o formato de exportação</h2>\n<p>Escolha JPG para fotos que você planeja compartilhar. Ele mantém os arquivos pequenos e funciona em todo lugar, e uma qualidade alta mantém a foto com contraste editado limpa.</p>\n<p>Escolha PNG para capturas de tela e gráficos com texto. O PNG não tem perda, então as bordas das letras ficam nítidas, e ele preserva a transparência quando você precisa.</p>\n<p>Escolha WebP quando quiser arquivos pequenos com boa qualidade. Ele funciona bem para imagens de web, embora alguns sistemas mais antigos ainda rejeitem o formato.</p>\n<p>Lembre que o controle de qualidade some para PNG, porque o PNG não tem perda e não tem ajuste de qualidade. Isso é comportamento normal, não um problema da ferramenta.</p>\n<h2 id=\"adjusting-on-mobile\">Como ajustar o contraste no celular ou no tablet</h2>\n<p>A ferramenta funciona em telas de toque, então dá para corrigir uma foto chapada no próprio celular que a tirou. Envie da sua galeria, arraste o controle com o dedo e baixe o resultado.</p>\n<p>Arrastar um controle com o dedo é menos preciso que com o mouse. Use as predefinições rápidas para valores exatos e depois ajuste com arrastes pequenos.</p>\n<p>Confira a prévia em tamanho real antes de baixar. Uma mudança de contraste que parece boa na tela pequena do celular pode ficar forte demais quando vista no computador.</p>\n<p>Os arquivos baixados vão para a sua pasta de downloads. De lá, você pode compartilhar a foto editada direto num aplicativo de conversa, num e-mail ou num post de rede social.</p>\n<h2 id=\"troubleshooting\">Solução de problemas comuns de contraste</h2>\n<p>Se a foto parecer dura, o controle está alto demais. Reduza em passos pequenos até a pele, o céu e as áreas de sombra mostrarem textura de novo.</p>\n<p>Se a foto continuar chapada depois do reforço, a original pode ter neblina demais para salvar. Uma foto tirada através de nevoeiro espesso não ganha detalhe que nunca foi capturado.</p>\n<p>Se os realces estiverem cortados, reduza o controle e confira as áreas claras em tamanho real. Uma pequena redução geralmente restaura o detalhe das nuvens ou da pele.</p>\n<p>Se a prévia parecer diferente do download, confira o formato e a qualidade de exportação. Uma qualidade JPG baixa pode suavizar a imagem inteira, inclusive as bordas de contraste.</p>\n<h2 id=\"contrast-plus-brightness\">Contraste mais brilho: a dupla comum</h2>\n<p>Uma foto escura e chapada precisa de brilho e contraste juntos. Clareie primeiro para levantar o nível geral e depois adicione contraste para restaurar a profundidade.</p>\n<p>Use o <a href=\"/pt/ajustar-brilho-da-imagem/\">ajustar o brilho da foto</a> antes de adicionar contraste, quando a imagem estiver escura. Um reforço de contraste numa foto escura só aprofunda as sombras.</p>\n<p>Faça os passos em ordem: brilho primeiro, depois contraste. Inverter pode deixar o ajuste de contraste mais difícil de avaliar, porque a imagem continua escura.</p>\n<p>Confira a comparação depois de cada passo. A comparação dividida mostra exatamente o que cada ajuste fez, para você parar quando a foto ficar certa.</p>\n<h2 id=\"saving-settings\">Como guardar seus ajustes para a próxima vez</h2>\n<p>Anote o valor de contraste que funcionou para um conjunto de fotos parecidas. Uma anotação curta, como paisagens com neblina mais 20 por cento, evita adivinhar na próxima vez.</p>\n<p>Para um lote de fotos tiradas com a mesma luz, use o mesmo valor para todas. Um contraste consistente num conjunto parece profissional, enquanto valores misturados parecem aleatórios.</p>\n<p>Guarde os arquivos originais. Um valor de contraste que funciona para uma foto pode não servir para outra, e a original permite testar outro nível sem dano extra.</p>\n<p>Revise suas anotações de vez em quando. Conforme sua câmera e sua iluminação melhoram, os valores de contraste de que você precisa vão mudar, e anotações antigas podem enganar.</p>\n<h2 id=\"quick-tips\">Dicas rápidas para um contraste melhor</h2>\n<p>Ajuste em passos pequenos. Uma mudança de 5 por cento por vez dá controle, enquanto um salto grande pode passar do valor certo antes de você perceber.</p>\n<p>Confira os extremos, não só o meio. Uma foto está com contraste demais quando os realces cortam ou as sombras esmagam, mesmo que os tons médios pareçam bons.</p>\n<p>Use a comparação sempre. Uma olhada rápida na original ao lado da edição pega erros que uma prévia pequena esconde.</p>\n<p>Guarde a foto original sem edições. Depois que uma mudança de contraste é aplicada numa exportação, não dá para desfazê-la a partir daquele arquivo.</p>\n<h2 id=\"contrast-for-product-photo\">Como adicionar contraste a uma foto de produto</h2>\n<p>Fotos de produto precisam de contraste claro para o item se destacar do fundo. Uma foto de produto chapada parece sem graça, enquanto uma marcante atrai o olhar para o item.</p>\n<p>Use um reforço moderado, de 10 a 20 por cento, para a maioria dos produtos. O item deve parecer sólido e definido, com bordas claras contra o fundo.</p>\n<p>Observe as cores do produto enquanto aumenta o contraste. Um reforço forte demais pode deixar as cores duras, então confira o item em si, não só o fundo.</p>\n<p>Mantenha o contraste consistente em todo o catálogo. Uma loja com níveis de contraste iguais parece organizada e confiável, enquanto níveis misturados parecem descuido.</p>\n<p>Para a comparação, leia <a href=\"/pt/blog/brilho-vs-exposicao-vs-contraste/\">Brilho, exposição e contraste: qual a diferença?</a>. Para a visão geral, veja <a href=\"/pt/blog/como-aumentar-contraste-da-foto/\">Como aumentar o contraste da foto: guia completo</a>, e para corrigir uma foto escura antes de adicionar contraste, experimente o <a href=\"/pt/ajustar-brilho-da-imagem/\">ajustar o brilho da foto</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Como adiciono contraste a uma foto no celular?","answer":"Abra a ferramenta de ajuste de contraste da foto no navegador do celular, envie a foto da sua galeria e arraste o controle para a direita com o dedo. Use um ajuste pronto para um valor exato, confira a comparação e baixe o resultado."},{"question":"Qual valor de contraste devo usar para uma paisagem com neblina?","answer":"Comece em mais 15 a 20 por cento e confira o céu. A neblina achata a faixa tonal, então um reforço moderado restaura a profundidade. Pare antes que as nuvens virem brancos vazios, e reduza o controle se os realces cortarem."},{"question":"Dá para reduzir o contraste e suavizar um retrato duro?","answer":"Sim. Arraste o controle para a esquerda, para valores negativos, como menos 10 ou menos 20 por cento. O contraste negativo suaviza sombras fortes no rosto sem perder a forma dele. Confira a pele para continuar definida e não virar cinza."},{"question":"Por que os realces da minha foto viram branco depois de adicionar contraste?","answer":"O contraste foi levado longe demais, o que corta as áreas mais claras em branco puro. Reduza o controle em passos pequenos até as nuvens, a pele e as superfícies brancas mostrarem detalhe de novo. Um reforço de 10 a 20 por cento costuma bastar."},{"question":"Devo ajustar o contraste antes ou depois do brilho?","answer":"Brilho primeiro, depois contraste. O brilho define o nível geral, e o contraste refina a amplitude ao redor desse nível. Uma foto escura precisa clarear antes do contraste, pois só o contraste não corrige o nível."},{"question":"Dá para desfazer uma mudança de contraste depois de baixar?","answer":"Não a partir do arquivo baixado, pois a mudança é aplicada na exportação. Guarde a foto original para testar outro nível de contraste. Na ferramenta, use a opção de redefinir para voltar a zero antes de baixar."}];
